fn rows(s:&State)->Vec<(String,String)>{let b=|v:bool|if v{"ON"}else{"OFF"}.to_string();match s.page{1=>vec![("Sandbox".into(),b(s.settings.sandbox)),("Free shopping".into(),b(s.settings.free_shop)),("Live game clock".into(),format!("{}x",s.settings.rate)),("Diagnostics".into(),"Save report".into())],2=>vec![("Texture decoding".into(),if s.settings.normalize{"Standard RGBA"}else{"Original"}.into()),("Inspect all crop stages".into(),"Tomatoes included".into()),("Graphics report".into(),"Save report".into())],3=>["Desktop / automatic","iPhone 16 Pro framing","Fold3 inner framing","Fold3 cover framing"].iter().enumerate().map(|(i,t)|(t.to_string(),if i==s.settings.profile as usize{"Selected"}else{""}.into())).collect(),4=>vec![("Preview original crops".into(),"Tomatoes first".into()),("Run crop inspection".into(),format!("{} flags",audit().flagged)),("Original asset recovery".into(),"Read report".into()),("Save full report".into(),"JSON".into())],_=>vec![("Sandbox".into(),"Clock & shop".into()),("Graphics".into(),"Original artwork".into()),("Screen fit".into(),"Desktop & phone".into()),("Crop inspector".into(),format!("{} flags",audit().flagged)),("Return to farm".into(),"".into())]}}
