#[cfg(test)]mod tests{use super::*;#[test]fn settings_validation(){let mut s=Settings{rate:999,tab_x:f32::NAN,profile:99,..Settings::default()};s.sanitize();assert_eq!(s.rate,1);assert_eq!(s.profile,3);assert!(s.tab_x.is_finite());assert_eq!(s.effective_rate(),1.);}#[test]fn clock_switch_is_continuous(){let mut c=Clock{guest:1000.,real:Instant::now()-Duration::from_secs(2),rate:10.};let before=c.value();assert!((before-1020.).abs()<0.1);c.change(1.);assert!((c.value()-before).abs()<0.05);}#[test]fn panel_fits(){for(w,h)in[(960,640),(1100,506),(900,720),(1160,426),(320,240)]{let(x,y,s)=fit(w,h);assert!(x>=0.&&y>=0.);assert!(x+400.*s<=w as f32);assert!(y+454.*s<=h as f32);}}}
